	<script>const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.site-nav');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});document.querySelectorAll('.site-nav a').forEach(link=>link.addEventListener('click',()=>{toggle.setAttribute('aria-expanded','false');nav.classList.remove('open')}));const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');document.querySelectorAll('.culture-grid#culture-carousel-track,.gallery-grid#gallery-carousel-track').forEach(track=>{const items=Array.from(track.children),controls=track.parentElement.querySelectorAll('[data-carousel-direction]');if(items.length<2)return;const step=()=>items[0].getBoundingClientRect().width+(parseFloat(getComputedStyle(track).columnGap)||0);const move=direction=>{const end=track.scrollWidth-track.clientWidth-2;if(direction>0&&track.scrollLeft>=end)track.scrollTo({left:0,behavior:reducedMotion.matches?'auto':'smooth'});else if(direction<0&&track.scrollLeft<=2)track.scrollTo({left:end,behavior:reducedMotion.matches?'auto':'smooth'});else track.scrollBy({left:direction*step(),behavior:reducedMotion.matches?'auto':'smooth'});};controls.forEach(button=>button.addEventListener('click',()=>move(button.dataset.carouselDirection==='next'?1:-1)));let timer;const stop=()=>clearInterval(timer);const start=()=>{stop();if(!reducedMotion.matches&&document.visibilityState==='visible')timer=setInterval(()=>move(1),5000);};track.parentElement.addEventListener('mouseenter',stop);track.parentElement.addEventListener('mouseleave',start);track.parentElement.addEventListener('focusin',stop);track.parentElement.addEventListener('focusout',event=>{if(!track.parentElement.contains(event.relatedTarget))start();});document.addEventListener('visibilitychange',start);reducedMotion.addEventListener?.('change',start);start();});</script>
